<?php
require_once __DIR__.'/../core/Auth.php';require_once __DIR__.'/../core/Database.php';require_once __DIR__.'/../core/Response.php';require_once __DIR__.'/../core/HrModule.php';Auth::requirePermission('hr_assessments.manage');$pageTitle='مدیریت آزمون‌های سازمانی';
if($_SERVER['REQUEST_METHOD']==='POST'){if(!Auth::verifyCsrf($_POST['csrf_token']??'')){http_response_code(419);exit('درخواست نامعتبر است.');}try{$action=$_POST['action']??'';if($action==='test')Database::execute('UPDATE hr_assessment_tests SET title=?,description=?,time_limit_minutes=?,active=?,updated_at=NOW() WHERE id=?',[trim($_POST['title']),trim($_POST['description']),max(1,(int)$_POST['time_limit_minutes']),isset($_POST['active'])?1:0,(int)$_POST['id']]);elseif($action==='question'){$questionId=(int)($_POST['question_id']??0);$testId=(int)$_POST['test_id'];$text=trim($_POST['question_text']);$answerType=in_array($_POST['answer_type']??'', ['scale_1_5','scale_1_7','yesno','choice','text'],true)?$_POST['answer_type']:'scale_1_5';$options=trim($_POST['options_json']??'');if($options!==''&&json_decode($options,true)===null&&json_last_error()!==JSON_ERROR_NONE)throw new RuntimeException('invalid_options');$values=[trim($_POST['question_code']??''),$text,hash('sha256',mb_strtolower($text,'UTF-8')),$answerType,$options?:null,trim($_POST['dimension_key']??''),max(.01,(float)$_POST['weight']),isset($_POST['reverse_score'])?1:0,(int)$_POST['sort_order'],trim($_POST['admin_note']??'')?:null];if($questionId){$question=Database::fetch('SELECT id FROM hr_assessment_questions WHERE id=? AND test_id=? AND COALESCE(is_seeded,seeded,0)=0',[$questionId,$testId]);if(!$question){http_response_code(403);exit('ویرایش سؤال پیش‌فرض مجاز نیست.');}Database::execute('UPDATE hr_assessment_questions SET question_code=?,question_text=?,question_hash=?,answer_type=?,options_json=?,dimension_key=?,weight=?,reverse_score=?,sort_order=?,admin_note=?,updated_at=NOW() WHERE id=?',array_merge($values,[$questionId]));}else Database::execute('INSERT INTO hr_assessment_questions(test_id,question_code,question_text,question_hash,answer_type,options_json,dimension_key,weight,reverse_score,required,sort_order,active,seeded,is_seeded,admin_note,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,1,?,1,0,0,?,NOW(),NOW())',array_merge([$testId],$values));}flash('عملیات با موفقیت انجام شد.');}catch(Throwable $e){error_log('Assessment test save: '.$e->getMessage());flash($e->getMessage()==='invalid_options'?'ساختار JSON گزینه‌ها معتبر نیست.':'خطا در ذخیره‌سازی اطلاعات. لطفاً مجدد تلاش کنید.','danger');}redirect('/admin/hr-assessment-tests.php?test_id='.(int)($_POST['test_id']??$_POST['id']??0));}
$tests=Database::fetchAll('SELECT t.*,(SELECT COUNT(*) FROM hr_assessment_questions q WHERE q.test_id=t.id) question_count FROM hr_assessment_tests t ORDER BY sort_order');$testId=(int)($_GET['test_id']??($tests[0]['id']??0));$test=$testId?Database::fetch('SELECT * FROM hr_assessment_tests WHERE id=?',[$testId]):null;$dimensions=$testId?Database::fetchAll('SELECT * FROM hr_assessment_dimensions WHERE test_id=? ORDER BY sort_order',[$testId]):[];$questions=$testId?Database::fetchAll('SELECT * FROM hr_assessment_questions WHERE test_id=? ORDER BY sort_order LIMIT 250',[$testId]):[];$editQuestion=isset($_GET['edit_question'])?Database::fetch('SELECT * FROM hr_assessment_questions WHERE id=? AND test_id=? AND COALESCE(is_seeded,seeded,0)=0',[(int)$_GET['edit_question'],$testId]):null;require __DIR__.'/../views/partials/admin-header.php';?>
<?php $seedMeta = HrModule::sobhanAssessmentData()['meta']; $currentSeed = Database::fetch('SELECT version FROM hr_assessment_seed_versions WHERE seed_key=? ORDER BY id DESC LIMIT 1', [$seedMeta['seed_key'] ?? '']); $templatePendingCount = (int)Database::fetch('SELECT COUNT(*) c FROM hr_assessment_questions WHERE answer_type IN ("choice","scenario_choice") AND (correct_answer_json IS NULL OR correct_answer_json="")')['c']; ?>
<section class="card"><div class="grid grid-3"><div><strong><?=count($tests)?></strong><div class="muted">تعداد تست‌ها</div></div><div><strong><?=$templatePendingCount?></strong><div class="muted">سؤال pending key</div></div><div><strong><?=e($currentSeed['version'] ?? 'ثبت نشده')?></strong><div class="muted">نسخه نصب‌شده</div></div></div></section>
<div class="grid grid-2"><section class="card"><h2>آزمون‌ها</h2><div class="table-wrap"><table><thead><tr><th>عنوان</th><th>کد</th><th>سؤال</th><th>وضعیت</th></tr></thead><tbody><?php foreach($tests as $t):?><tr><td><a href="?test_id=<?=$t['id']?>"><?=e($t['title'])?></a></td><td><code><?=e($t['code'])?></code></td><td><?=e($t['question_count'])?></td><td><?=$t['active']?'فعال':'غیرفعال'?></td></tr><?php endforeach?></tbody></table></div></section><?php if($test):?><section class="card admin-form"><h2>ویرایش آزمون</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="action" value="test"><input type="hidden" name="id" value="<?=$test['id']?>"><label class="form-field"><span>عنوان</span><input name="title" value="<?=e($test['title'])?>"></label><label class="form-field"><span>توضیح</span><textarea name="description" rows="5"><?=e($test['description'])?></textarea></label><label class="form-field"><span>زمان تخمینی</span><input type="number" name="time_limit_minutes" value="<?=$test['time_limit_minutes']?>"></label><label class="checkbox-item"><input type="checkbox" name="active" <?=$test['active']?'checked':''?>> فعال</label><button class="btn btn-primary">ذخیره</button></form></section><?php endif?></div>
<?php if($test):?><section class="card"><h2>ابعاد آزمون</h2><div class="actions"><?php foreach($dimensions as $d):?><span class="badge"><?=e($d['dimension_label'].' ('.$d['dimension_key'].')')?></span><?php endforeach?></div></section><section class="card admin-form"><h2><?=$editQuestion?'ویرایش سؤال سفارشی':'افزودن سؤال HR-safe'?></h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="action" value="question"><input type="hidden" name="test_id" value="<?=$testId?>"><input type="hidden" name="question_id" value="<?=e($editQuestion['id']??'')?>"><div class="grid grid-2"><label class="form-field"><span>کد سؤال</span><input name="question_code" value="<?=e($editQuestion['question_code']??'')?>"></label><label class="form-field"><span>وزن</span><input type="number" step=".01" name="weight" value="<?=e($editQuestion['weight']??1)?>"></label></div><label class="form-field"><span>متن سؤال</span><textarea name="question_text" required><?=e($editQuestion['question_text']??'')?></textarea></label><div class="grid grid-3"><label class="form-field"><span>نوع پاسخ</span><select name="answer_type"><?php foreach(['scale_1_5','scale_1_7','yesno','choice','text'] as $type):?><option <?=$type===($editQuestion['answer_type']??'scale_1_5')?'selected':''?>><?=e($type)?></option><?php endforeach?></select></label><label class="form-field"><span>بعد</span><select name="dimension_key"><?php foreach($dimensions as $d):?><option value="<?=e($d['dimension_key'])?>" <?=$d['dimension_key']===($editQuestion['dimension_key']??'')?'selected':''?>><?=e($d['dimension_label'])?></option><?php endforeach?></select></label><label class="form-field"><span>JSON گزینه‌ها</span><input dir="ltr" name="options_json" value="<?=e($editQuestion['options_json']??'')?>"></label><label class="form-field"><span>ترتیب</span><input type="number" name="sort_order" value="<?=e($editQuestion['sort_order']??1000)?>"></label><label class="checkbox-item"><input type="checkbox" name="reverse_score" <?=!empty($editQuestion['reverse_score'])?'checked':''?>> نمره‌گذاری معکوس</label></div><label class="form-field"><span>یادداشت ادمین</span><textarea name="admin_note" rows="3"><?=e($editQuestion['admin_note']??'')?></textarea></label><button class="btn btn-primary">ذخیره</button></form></section><section class="card"><h2>سؤال‌ها</h2><div class="table-wrap"><table><thead><tr><th>#</th><th>کد</th><th>سؤال</th><th>نوع</th><th>بعد</th><th>منبع</th><th></th></tr></thead><tbody><?php foreach($questions as $q):$isSeeded=(int)($q['is_seeded']??$q['seeded']??0)===1;?><tr><td><?=$q['sort_order']?></td><td><code><?=e($q['question_code']?:'-')?></code></td><td><?=e($q['question_text'])?><?php if(!empty($q['admin_note'])):?><div class="muted"><?=e($q['admin_note'])?></div><?php endif?></td><td><?=e($q['answer_type'])?></td><td><?=e($q['dimension_key'])?></td><td><?=$isSeeded?'پیش‌فرض':'سفارشی'?></td><td><?php if(!$isSeeded):?><a class="btn btn-small" href="?test_id=<?=$testId?>&edit_question=<?=$q['id']?>">ویرایش</a><?php endif?></td></tr><?php endforeach?></tbody></table></div></section><?php endif?>
</section></main></div><script src="/assets/js/app.js"></script></body></html>
